// Found in src/collections/batch.rs around batch processing
pub async fn batch_update_points(
    &self,
    collection_name: &str,
    operations: Vec<BatchOperation>,
    wait: bool,
) -> Result<BatchUpdateResponse> {
    // Vector dimension validation happens BEFORE batch execution
    for operation in &operations {
        if let BatchOperation::Upsert { points } = operation {
            for point in points {
                if let Err(e) = self.validate_vector_dimension(point) {
                    // Early return on validation failure - no execution
                    return Err(BatchError::ValidationError(e));
                }
            }
        }
    }
    // If we reach here, all validations passed - proceed with atomic batch
}

// Vector dimension validation logic
fn validate_vector_dimension(&self, point: &PointStruct) -> Result<(), VectorError> {
    let expected_dim = self.collection_config.vector_size;
    let actual_dim = point.vector.len();
    if actual_dim != expected_dim {
        return Err(VectorError::DimensionMismatch {
            expected: expected_dim,
            actual: actual_dim,
        });
    }
    Ok(())
}
